package variant;
public class Example {
public java.util.function.IntUnaryOperator addition(int first){java.util.function.IntFunction<java.util.function.IntUnaryOperator> factory=x->y->Math.addExact(x,y);return factory.apply(first);}public java.util.function.Predicate<String> matcher(String regex){java.util.function.Function<String,java.util.function.Predicate<String>> factory=r->java.util.regex.Pattern.compile(r).asMatchPredicate();return factory.apply(regex);}public java.util.function.Function<String,String[]> splitter(String regex){java.util.function.Function<String,java.util.function.Function<String,String[]>> factory=r->{var p=java.util.regex.Pattern.compile(r);return s->p.split(s,-1);};return factory.apply(regex);}public void demonstrate(){var add=addition(7);System.out.println(add.applyAsInt(-2));System.out.println(add.applyAsInt(3));var test=matcher("[A-Z]+");System.out.println(test.test("ABC"));System.out.println(test.test("Ab"));var split=splitter(",");for(String text:new String[]{"a,,b,",""})System.out.println(java.util.Arrays.toString(split.apply(text))+" length="+split.apply(text).length);}
}
